const now = Date.now();
const rows = items.map(i => i.json).filter(r => {
  const vid = r.youtubeVideoId || r.YoutubeVideoId || '';
  const status = String(r.status || r.Status || '').toUpperCase();
  const date = new Date(r.date || r.Date || 0).getTime();
  if (!vid || !date || status !== 'PUBLISHED') return false;
  const daysAgo = (now - date) / 86400000;
  return daysAgo >= 6.5 && daysAgo <= 8.2;
}).map(r => ({
  ...r,
  analyticsWindow: "7D"
}));

if (!rows.length) return [{ json: { noVideos: true, analyticsWindow: "7D", message: 'No videos need 7D analytics update' } }];
return rows.map(r => ({ json: r }));

const analytics = items[0].json || {};
const rows = analytics.rows || [];
const headers = analytics.columnHeaders || [];
const col = {};
headers.forEach((h, i) => { col[h.name] = i; });
const cfg = (() => {
  try { return $('7-Day Validate Config').first().json || {}; }
  catch (e) { return {}; }
})();

const videos = (() => {
  try {
    return $('Filter 7-Day Old Videos').all().map(i => i.json).filter(v => v.youtubeVideoId);
  } catch (e) {
    return [];
  }
})();

function normalizeFamily(title = '', topic = '') {
  return String(topic || title || '')
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/\b(best|free|cheap|cheaper|how|to|for|vs|and|the|a|an|is|still|worth|paying|manual|smart|automation|automate|workflow|tool|tools|app|apps|local|business|businesses|service|services|small|ai|software|stack)\b/g, ' ')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .filter(Boolean)
    .slice(0, 4)
    .join('-') || 'general';
}

function buildSequelIdeas(title = '', topic = '') {
  const base = title || topic || 'this topic';
  return [
    `${base} for beginners`,
    `${topic || base} mistakes to avoid`,
    `${topic || base} cheaper/free version`
  ].slice(0, 3);
}

const results = videos.map(v => {
  const vid = v.youtubeVideoId || '';
  const row = rows.find(r => r[col['video']] === vid) || [];
  const views = Number(row[col['views']] || 0);
  const avgPct = Number(row[col['averageViewPercentage']] || 0);
  const avgDur = Number(row[col['averageViewDuration']] || 0);
  const likes = Number(row[col['likes']] || 0);
  const subs = Number(row[col['subscribersGained']] || 0);
  const watchMins = Number(row[col['estimatedMinutesWatched']] || 0);
  const impressions = Number(row[col['videoThumbnailImpressions']] || 0);
  const ctr = Number(row[col['videoThumbnailImpressionsClickRate']] || 0);

  const packagingScore = Math.min(10, Number(((ctr * 1.35) + (impressions >= 1500 ? 2.4 : impressions >= 500 ? 1.2 : 0) + (views >= 700 ? 0.9 : 0)).toFixed(1)));
  const retentionScore = Math.min(10, Number((((avgPct / 10) * 1.2) + (avgDur >= 240 ? 1.7 : avgDur >= 120 ? 0.9 : 0)).toFixed(1)));

  let score = 0;
  if (views >= 12000) score += 3.1; else if (views >= 4000) score += 2.2; else if (views >= 700) score += 1.2;
  if (avgPct >= 48) score += 2.1; else if (avgPct >= 34) score += 1.3; else if (avgPct >= 25) score += 0.4;
  if (ctr >= 6.5) score += 2.4; else if (ctr >= 4.8) score += 1.5; else if (ctr >= 3.0) score += 0.6;
  if (subs > 0) score += 0.5;
  if (likes > 50) score += 0.6; else if (likes > 10) score += 0.25;
  const realScore = Math.min(10, Math.round(score * 10) / 10);

  let growthAction = 'HOLD';
  let growthReason = 'Gather more data';
  let secondaryAction = 'NONE';
  if (impressions >= 350 && ctr < 2.9) {
    growthAction = 'REPACKAGE_TITLE_THUMB';
    growthReason = 'Topic is getting seen but packaging is underperforming';
    secondaryAction = 'TRY_NEW_THUMBNAIL_VARIANT';
  } else if (ctr >= 4.4 && avgPct < 30) {
    growthAction = 'FIX_HOOK_RETENTION';
    growthReason = 'Clicks are happening but the opening does not hold viewers';
    secondaryAction = 'TIGHTEN_OPENING_30_SECONDS';
  } else if (ctr >= 4.8 && avgPct >= 36 && views >= 500) {
    growthAction = 'MAKE_SEQUEL';
    growthReason = 'Broad packaging and useful retention are both working';
    secondaryAction = 'DOUBLE_DOWN_ON_FORMAT';
  } else if (views < 150 && avgPct < 23) {
    growthAction = 'DO_NOT_REPEAT';
    growthReason = 'The topic did not earn either reach or hold';
    secondaryAction = 'SUPPRESS_LANE_2_WEEKS';
  }

  const offerUrl = String(v.oneLinkOfferUrl || '');
  const offerReady = !!offerUrl && !offerUrl.includes('PASTE_');
  const offerAction = (!offerReady && Number(v.firstDollarScore || 0) >= 7)
    ? 'BUILD_PRIMARY_OFFER_URL'
    : (views >= 300 && Number(v.firstDollarScore || 0) >= 7 && subs === 0)
      ? 'TIGHTEN_ONE_LINK_CTA'
      : 'HOLD_OFFER';

  const franchiseFamily = normalizeFamily(v.title || v.Title || '', v.topic || v.Topic || '');
  const franchiseStrength = Math.min(10, Number(((realScore * 0.5) + (packagingScore * 0.35) + (retentionScore * 0.15)).toFixed(1)));
  const franchiseReady = growthAction === 'MAKE_SEQUEL' || franchiseStrength >= 7.8;

  return {
    analyticsWindow: '7D',
    youtubeVideoId: vid,
    topic: v.topic || v.Topic || '',
    title: v.title || v.Title || '',
    predictedScore: Number(v.score || v.Score || 0),
    realScore,
    realViews: views,
    realAvgRetention: avgPct,
    realAvgViewDuration: avgDur,
    realLikes: likes,
    realSubs: subs,
    realWatchMins: watchMins,
    thumbImpressions: impressions,
    thumbCtr: ctr,
    packagingScore,
    retentionScore,
    scoreDelta: realScore - Number(v.score || v.Score || 0),
    date: v.date || v.Date || '',
    growthAction,
    growthReason,
    secondaryAction,
    offerAction,
    sequelIdeas: buildSequelIdeas(v.title || v.Title || '', v.topic || v.Topic || ''),
    winnerFollowupNeeded: growthAction === 'MAKE_SEQUEL',
    repackageNeeded: growthAction === 'REPACKAGE_TITLE_THUMB',
    suppressLane: growthAction === 'DO_NOT_REPEAT',
    offerUrl,
    offerReady,
    franchiseFamily,
    franchiseStrength,
    franchiseReady,
    openingQualityScore: Number(v.openingQualityScore || 0),
    finalBusinessScore: Number(v.finalBusinessScore || 0)
  };
});

return results.map(r => ({ json: r }));

